#include "test_time.h"
#include "../../../../../tf_common/tf_uart_comms.h"
#include "../../../../../tf_common/tf_test_results.h"
#include <stdio.h>
#include <Hal.h>

static bool bResultReported = false;
static unsigned long long ullStartTimeNs = 0;


#define EXPECTED_INTERVAL_MS 700ULL
#if COVERAGE_ENABLED == 0
#define TIME_TOLERANCE_MS 10ULL     // Allow some tolerance since we are depending on the scheduler not being too busy running other tasks in this model
#else
#define TIME_TOLERANCE_MS 20ULL     // Allow greater tolerance since for coverage we really do not care about timing
#endif
#define EXPECTED_INTERVAL_MIN (EXPECTED_INTERVAL_MS - TIME_TOLERANCE_MS)
#define EXPECTED_INTERVAL_MAX (EXPECTED_INTERVAL_MS + TIME_TOLERANCE_MS)
#define NS_IN_ONE_MS 1000000ULL


// Constructor
void test_time_startup(void)
{
    // Register the test that this TASTE Function will submit a result for
    testresult_register_test(TF_TEST_ID__TestTime);
}



// Captures the Hal time at the point when invoked
void test_time_PI_trigger_start( void )
{
    // Only capture the start time if what we have is zero
    if (ullStartTimeNs == 0)
    {
        ullStartTimeNs = Hal_GetElapsedTimeInNs();
    }
}


// Determine pass/fail
// This function is called 700 ms after the first
void test_time_PI_trigger_check(void)
{
    char aMsgBuff[100];
    unsigned long long ullElapsedTimeMs = 0;

    // Skip this if we already reported a result, or if we do not yet have the start time
    if (bResultReported || ullStartTimeNs == 0)
    {
        return;
    }

    transmit_log_info("test_time_PI_trigger_check -> invoked");

    // Determine the elapsed time
    ullElapsedTimeMs = (Hal_GetElapsedTimeInNs() - ullStartTimeNs) / NS_IN_ONE_MS;

    // Measurement of elapsed time is withi expectations?
    if (ullElapsedTimeMs >= EXPECTED_INTERVAL_MIN && ullElapsedTimeMs <= EXPECTED_INTERVAL_MAX)
    {
        testresult_report_pass(TF_TEST_ID__TestTime);
    }
    else
    {
        sprintf(aMsgBuff, "Measurement of elapsed time was not in range %llu->%llu ms but rather was %llu ms", EXPECTED_INTERVAL_MIN, EXPECTED_INTERVAL_MAX, ullElapsedTimeMs);
        testresult_report_fail(TF_TEST_ID__TestTime, aMsgBuff);
    }

    // Only report the result once
    bResultReported = true;
}


